def solve(g):
    n=len(g); N=range(n)
    # detect reflection a -> c-a consistent on non-6 cells
    best=None
    for c in range(n-1, 2*n):
        ok=0; bad=0
        for i in N:
            a=c-i
            if not (0<=a<n): continue
            for j in N:
                if g[i][j]!=6 and g[a][j]!=6 and g[i][j]!=g[a][j]: bad+=1
        if bad==0:
            cov=sum(1 for i in N if 0<=c-i<n)
            if best is None or cov>best[1]: best=(c,cov)
    c=best[0] if best else None
    known={(i,j):g[i][j] for i in N for j in N if g[i][j]!=6}
    def sources(i,j):
        s=[(j,i)]
        if c is not None:
            for a,b in [(c-i,j),(i,c-j),(c-i,c-j)]:
                if 0<=a<n and 0<=b<n and 2<=i<n and 2<=j<n and 2<=a<n and 2<=b<n:
                    s.append((a,b))
        return s
    changed=True
    while changed:
        changed=False
        for i in N:
            for j in N:
                if (i,j) in known: continue
                vals={known[s] for s in sources(i,j) if s in known}
                if len(vals)==1:
                    known[(i,j)]=vals.pop(); changed=True
    return [[known.get((i,j),6) for j in N] for i in N], c, all((i,j) in known for i in N for j in N)
